package com.byawasaya.platform.admin;
import java.math.BigDecimal; import java.util.List; import java.util.UUID;
import org.springframework.cache.annotation.CacheEvict; import org.springframework.cache.annotation.Cacheable; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
import com.byawasaya.platform.business.Business; import com.byawasaya.platform.business.BusinessRepository; import com.byawasaya.platform.business.BusinessStatus; import com.byawasaya.platform.business.BusinessPlan; import com.byawasaya.platform.orders.CustomerOrderRepository; import com.byawasaya.platform.orders.OrderStatus; import com.byawasaya.platform.auth.UserAccount; import com.byawasaya.platform.auth.UserAccountRepository; import com.byawasaya.platform.auth.TokenService; import com.byawasaya.platform.audit.AuditService;
@Service @Transactional(readOnly=true)
public class AdminService {
 private final BusinessRepository businesses; private final CustomerOrderRepository orders; private final UserAccountRepository accounts; private final org.springframework.jdbc.core.JdbcTemplate jdbc; private final com.byawasaya.platform.business.TenantTableNameResolver tables; private final TokenService sessions; private final AuditService audit;
 public AdminService(BusinessRepository businesses, CustomerOrderRepository orders, UserAccountRepository accounts, org.springframework.jdbc.core.JdbcTemplate jdbc, com.byawasaya.platform.business.TenantTableNameResolver tables,TokenService sessions,AuditService audit){this.businesses=businesses;this.orders=orders;this.accounts=accounts;this.jdbc=jdbc;this.tables=tables;this.sessions=sessions;this.audit=audit;}
 @Cacheable(cacheNames="adminDashboard",key="'overview'") public AdminDtos.DashboardResponse getDashboard(){var recent=businesses.findTop10ByOrderByCreatedAtDesc().stream().map(AdminDtos.BusinessResponse::from).toList();java.util.Set<java.util.UUID> migrated=new java.util.HashSet<>(jdbc.queryForList("SELECT business_id FROM tenant_provisioning WHERE status='READY'",java.util.UUID.class));var legacyOrders=orders.findAll().stream().filter(o->!migrated.contains(o.getBusinessId())).toList();BigDecimal sales=legacyOrders.stream().filter(o->o.getStatus()!=OrderStatus.CANCELLED).map(o->o.getTotalAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);long orderCount=legacyOrders.size();for(String prefix:jdbc.queryForList("SELECT table_prefix FROM tenant_provisioning WHERE status='READY'",String.class)){String orderTable=tables.table(prefix,"orders");Long count=jdbc.queryForObject("SELECT COUNT(*) FROM "+orderTable,Long.class);BigDecimal tenantSales=jdbc.queryForObject("SELECT COALESCE(SUM(total_amount),0) FROM "+orderTable+" WHERE status<>'CANCELLED'",BigDecimal.class);orderCount+=count==null?0:count;sales=sales.add(tenantSales==null?BigDecimal.ZERO:tenantSales);}return new AdminDtos.DashboardResponse(businesses.count(),businesses.countByStatus(BusinessStatus.ACTIVE),businesses.countByStatus(BusinessStatus.PENDING),orderCount,sales,recent);}
 public List<AdminDtos.BusinessResponse> getRecentBusinesses(){return businesses.findTop10ByOrderByCreatedAtDesc().stream().map(AdminDtos.BusinessResponse::from).toList();}
 public List<AdminDtos.BusinessResponse> getBusinesses(){return businesses.findAllByOrderByCreatedAtDesc().stream().map(AdminDtos.BusinessResponse::from).toList();}
 public List<AdminDtos.UserResponse> getUsers(){return accounts.findAllByOrderByCreatedAtDesc().stream().map(u -> AdminDtos.UserResponse.from(u, businesses.findById(u.getBusinessId()).map(Business::getName).orElse("—"))).toList();}
 @Transactional public AdminDtos.UserResponse setUserEnabled(UUID id, boolean enabled,String actor){UserAccount user=accounts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found."));user.setEnabled(enabled);if(!enabled)sessions.revokeUser(user.getUsername());audit.record(actor,"SUPERADMIN",user.getBusinessId(),enabled?"TENANT_USER_ENABLED":"TENANT_USER_DISABLED","USER",id.toString(),"SUCCESS","{}");return AdminDtos.UserResponse.from(user,businesses.findById(user.getBusinessId()).map(Business::getName).orElse("—"));}
 @CacheEvict(cacheNames="adminDashboard",key="'overview'") @Transactional public AdminDtos.BusinessResponse createBusiness(AdminDtos.CreateBusinessRequest r){Business b=new Business(r.name().trim(),r.ownerName().trim(),r.plan());while(businesses.existsByTenantTagIgnoreCase(b.getTenantTag()))b.setTenantTag("t_"+UUID.randomUUID().toString().replace("-","").substring(0,8));b.setStatus(BusinessStatus.PENDING);return AdminDtos.BusinessResponse.from(businesses.save(b));}
 @CacheEvict(cacheNames="adminDashboard",key="'overview'") @Transactional public AdminDtos.BusinessResponse updateStatus(UUID id,BusinessStatus status,String actor){Business b=businesses.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Business not found."));if(b.getStatus()==BusinessStatus.PENDING && status==BusinessStatus.ACTIVE)throw new ResponseStatusException(HttpStatus.CONFLICT,"Pending stores must be approved through the application verification workflow.");if(status==BusinessStatus.ACTIVE&&b.getStatus()==BusinessStatus.SUSPENDED&&tables.prefix(id).isPresent()){Long valid=jdbc.queryForObject("SELECT COUNT(*) FROM subscriptions WHERE business_id=? AND (status='ACTIVE' OR (status='TRIAL' AND trial_ends_at>now()))",Long.class,id);if(valid==null||valid==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Reactivate the subscription or trial before reactivating this store.");}b.setStatus(status);if(status==BusinessStatus.SUSPENDED){sessions.revokeBusiness(id);for(UserAccount u:accounts.findAllByBusinessId(id))sessions.revokeUser(u.getUsername());}audit.record(actor,"SUPERADMIN",id,"TENANT_STATUS_CHANGED","TENANT",id.toString(),"SUCCESS","{\"status\":\""+status.name()+"\"}");return AdminDtos.BusinessResponse.from(b);}
}
